<script setup>
const route=useRoute(),query=ref(''),type=ref(String(route.query.type||'')),category=ref('')
const {data:types}=await useFetch('/api/catalog/types')
const {data:categories}=await useFetch('/api/catalog/categories')
const {data:items,pending,error,refresh}=await useFetch('/api/catalog/content',{query:computed(()=>({q:query.value,type:type.value,category:category.value||undefined}))})
</script>
<template><main class="page"><div class="page-heading"><small>مسیر خودت را پیدا کن</small><h1>کشف آرامش</h1></div><label class="search-box"><AppIcon name="search"/><input v-model="query" placeholder="جست‌وجو: آرامش، ریکی، تنفس…" aria-label="جست‌وجوی محتوا"/></label><div class="rail filters"><button class="chip" :aria-pressed="!type" @click="type='';category=''">همه</button><button v-for="t in types" :key="t.id" class="chip" :aria-pressed="type===t.slug" @click="type=t.slug;category=''">{{t.title_fa}}</button></div><label class="field"><span>دسته‌بندی</span><select v-model="category" class="select"><option value="">همهٔ دسته‌ها</option><option v-for="c in (categories||[]).filter(c=>!type||c.taxonomy===type)" :key="c.id" :value="c.id">{{c.title_fa}}</option></select></label><div v-if="pending" class="state">در حال جست‌وجو…</div><div v-else-if="error" class="state">دریافت محتوا ممکن نشد.<button class="btn" @click="refresh()">تلاش دوباره</button></div><div v-else-if="!items?.length" class="state">هنوز محتوایی با این مشخصات نداریم. یک عبارت دیگر امتحان کن.</div><div v-else class="card-grid"><ContentCard v-for="item in items" :key="item.id" :item="item"/></div></main></template>
